/* Independent reference harness for the benchmark gold (NOT generated by Verity).
 * Links the real navgps-c sources with a hand-written HAL stub and prints ground truth. */
#include <stdio.h>
#include <string.h>
#include "gps_types.h"
#include "navigation.h"
#include "gps_receiver.h"
#include "ring_buffer.h"

ring_buffer_t g_gps_rx;                 /* normally defined in drivers/uart_isr.c */
static uint32_t now_ms = 1000;
static int steering_calls = 0, last_steer = -9999, led = -1;
uint32_t hal_get_tick_ms(void) { return now_ms; }
void motor_set_steering(int16_t a) { steering_calls++; last_steer = a; }
void led_set_status(int on) { led = on; }

static gps_fix_t mkfix(double hdg, double spd, int valid) {
    gps_fix_t f; memset(&f, 0, sizeof f);
    f.latitude = 33.6844; f.longitude = 73.0479; f.speed_knots = spd; f.heading_deg = hdg;
    f.hdop = 1.0f; f.satellites = 8; f.valid = valid; f.timestamp_ms = now_ms; return f;
}
static void reset(void) { navigation_init(33.7000, 73.0600); steering_calls = 0; last_steer = -9999; led = -1; now_ms = 1000; }

int main(void) {
    gps_fix_t f;
    /* A: heading 270, speed 80, valid, from the initial state (currentHeading = 0) */
    reset(); f = mkfix(270.0, 80.0, 1); ProcessGpsData(&f);
    printf("A.currentHeading=%.4f mode=%d\n", currentHeading, (int)g_nav.mode);
    now_ms += 100; NavigationTick(now_ms);
    printf("A.steering_calls=%d last_steer=%d\n", steering_calls, last_steer);
    /* A2: low speed keeps the previous heading */
    reset(); f = mkfix(270.0, 1.0, 1); ProcessGpsData(&f);
    printf("A2.currentHeading=%.4f\n", currentHeading);
    /* B: 5 invalid fixes -> degraded, no steering */
    reset(); for (int i = 0; i < 5; i++) { f = mkfix(270.0, 80.0, 0); ProcessGpsData(&f); }
    printf("B.mode=%d consecutive_invalid=%d\n", (int)g_nav.mode, g_nav.consecutive_invalid);
    now_ms += 100; NavigationTick(now_ms); printf("B.steering_calls=%d\n", steering_calls);
    /* C: GPS lost for > 2000 ms after a good fix -> HOLD, steering centred, LED off */
    reset(); f = mkfix(270.0, 80.0, 1); ProcessGpsData(&f);
    now_ms += 2100; NavigationTick(now_ms);
    printf("C.mode=%d steering_calls=%d last_steer=%d led=%d\n", (int)g_nav.mode, steering_calls, last_steer, led);
    /* D: full NMEA path through the dispatch table and the callback */
    reset(); gps_receiver_init(); gps_receiver_set_callback(ProcessGpsData);
    const char *gga = "$GPGGA,120000,3341.064,N,07302.874,E,1,08,0.9,500.0,M,0,M,,*"; char line[128]; unsigned cs = 0;
    for (const char *p = gga + 1; *p != '*'; p++) cs ^= (unsigned char)*p; snprintf(line, sizeof line, "%s%02X", gga, cs);
    printf("D.gga_rc=%d\n", gps_receiver_process_line(line));
    const char *rmc = "$GPRMC,120000,A,3341.064,N,07302.874,E,80.0,270.0,300926,,,A*"; cs = 0;
    for (const char *p = rmc + 1; *p != '*'; p++) cs ^= (unsigned char)*p; snprintf(line, sizeof line, "%s%02X", rmc, cs);
    printf("D.rmc_rc=%d currentHeading=%.4f lat=%.5f lon=%.5f mode=%d\n", gps_receiver_process_line(line), currentHeading, g_nav.latitude, g_nav.longitude, (int)g_nav.mode);
    printf("D.bad_checksum_rc=%d checksum_errors=%u\n", gps_receiver_process_line("$GPRMC,1,A*00"), g_gps_stats.checksum_errors);
    return 0;
}
